#!/usr/bin/env python3
"""
Round 126b (culprits), 2 October 2026. Needs round 125b.

The original Esri imagery back on the Satellite and atlas basemaps; the
live share at the top of the layer menu.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

HEAD = "## Round 126b (2 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round126b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 125b" not in text:
        sys.exit("round126b: round 125b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round126b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round126b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round126b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


NOTE = '## Round 126b (2 October)\n\nNeeds round 125b. No tiles patch. No app.js?v= bump.\n\n- Basemaps: the Satellite basemap\'s and the painted atlas\'s imagery and the\n  hillshade are Esri\'s again, exactly as before round 123b (the owner tuned\n  the looks on them). If Esri\'s "API key required" squares return close in,\n  the fix that keeps the look is a free ArcGIS key on the same imagery.\n- The live share moved to the top of the layer menu, above Combine the\n  ticked layers: "N% of the map\'s layers are live layers".\n\n'
DIFF = ""

if __name__ == "__main__":
    main()
